/* The upcoming list mirrors the main site's upcoming projects (assets/app.js, filled in by
   scripts/build-pages.cjs), so counts and names always match. Detailed land-bid files are kept
   where they exist (matched on pid); every other project gets a basic file. */
const ALIAS = {};
const REPORTED_NAME = {'lentor-signature': 1, 'clovelle-of-woodlands': 1, 'impressions-at-dairy-farm': 1};
if (SITE.up.length) {
  const rich = Object.fromEntries(NL.U.map(u => [u.pid, u]));
  const psfOf = t => { const m = /\$([\d,]+)\s*psf/.exec(t || ''); return m ? +m[1].replace(/,/g, '') : null; };
  NL.U = SITE.up.map(s => {
    const r = rich[s.pid], common = {name: s.name, slug: s.slug, pid: s.pid, reg: s.reg, mallSite: s.mall};
    if (r) { if (r.id !== s.slug) ALIAS[r.id] = s.slug; } if (r) return {...r, ...common, id: s.slug, oldId: r.id, alias: r.name, notes: REPORTED_NAME[r.id] ? [`Name reported by a listing site: ${r.name}. The developer has not confirmed it, so this page uses the site name.`, ...r.notes] : r.notes};
    return {basic: true, id: s.slug, ...common, alias: '', dev: s.dev, units: s.units ? (s.unitsEst ? 'about ' : '') + comma(s.units) : 'Not announced', where: s.where, launch: s.launch || 'Not announced', land: psfOf(s.landCost) || psfOf(/psf ppr/.test(s.desc) ? s.desc : ''), total: s.landCost || 'Not published', close: s.landDate || 'Not applicable', bids: null, bidders: [], nxt: [], analyst: 'Not compiled yet', site: null, mrt: s.mrt || 'To be confirmed', cq: 'Not checked yet', notes: s.desc ? [s.desc] : [], ec: s.ec, tenure: s.tenure || 'Not stated', src: s.src || []};
  });
}
