const LB = (SITE.launched || []).map(s => ({...s, id: s.slug, reg: (s.reg || '').toUpperCase(), soldOut: /sold out/i.test((NL.REF[s.slug] || {}).name || '') || !!(VSTAT[s.slug] || {}).out, v: VSTAT[s.slug] || null}));
const LBA = Object.fromEntries(LB.map(x => [x.id, x]));
const xov = id => { const x = XSCORE[id]; if (!x) return null; const five = Object.values(x.scores).reduce((a, v) => a + v[0], 0) / 5; return x.growth ? 0.4 * x.growth[0] + 0.6 * five : five; };
const xschool = id => !!XSCORE[id] && /primary school within 1 km \(\+1\)/.test(XSCORE[id].scores.loc[1]);
CONDOS.push(...LB.map(x => ({id: x.id, name: x.name, also_known_as: x.dev, area: x.where, nearest_mrt: x.mrt || '', district: '', coverage: 'Post-launch file'})));
const norm = s => s.toLowerCase().replace(/@/g, 'at').replace(/[^a-z0-9 ]/g, ' ').replace(/\bthe\b/g, ' ').replace(/\s+/g, ' ').trim();
function lev(a, b) { const m = a.length, n = b.length; if (!m) return n; if (!n) return m; let p = Array.from({length: n + 1}, (_, j) => j); for (let i = 1; i <= m; i++) { const c = [i]; for (let j = 1; j <= n; j++) c[j] = Math.min(p[j] + 1, c[j - 1] + 1, p[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1)); p = c; } return p[n]; }
function score(q, c) {
  const qn = norm(q); if (!qn) return 0;
  const hay = norm([c.name, c.also_known_as, c.area, c.nearest_mrt, c.district].join(' '));
  if (norm(c.name).startsWith(qn)) return 100;
  if (hay.includes(qn)) return 80;
  const words = hay.split(' '), qs = qn.split(' ');
  let s = 0;
  for (const w of qs) { let best = 0; for (const h of words) { if (h.startsWith(w)) best = Math.max(best, 30); else { const d = lev(w, h.slice(0, Math.max(w.length, 3))); const tol = w.length > 6 ? 2 : w.length > 3 ? 1 : 0; if (d <= tol) best = Math.max(best, 22 - d * 5); } } s += best; }
  return s / qs.length;
}
let cur = -1;
function showResults() {
  const q = $('#q').value, box = $('#results');
  if (!q.trim()) { box.hidden = true; return; }
  const hits = CONDOS.map(c => [score(q, c), c]).filter(x => x[0] > 10).sort((a, b) => b[0] - a[0]).slice(0, 7);
  box.innerHTML = '';
  if (!hits.length) box.append(el('div', {class: 'empty'}, `No condo matches “${q.replace(/</g, '&lt;')}” yet. Try Browse all condos to see everything that is in so far.`));
  hits.forEach(([, c], i) => { const b = el('button', {type: 'button', role: 'option', 'data-id': c.id}, `<span>${c.name} <span class="tag">· ${c.area}</span></span><span class="tag">${c.coverage}</span>`); b.addEventListener('mousedown', e => { e.preventDefault(); pick(c.id); }); box.append(b); });
  cur = hits.length ? 0 : -1; mark(); box.hidden = false;
}
function mark() { [...$('#results').querySelectorAll('button')].forEach((b, i) => b.classList.toggle('on', i === cur)); }
const BASE = '/condo-analysis/';
const pathOf = id => id === 'home' ? BASE : BASE + id + '/';
const known = id => id === 'home' || CONDOS.some(c => c.id === id);
const unalias = id => ALIAS[id] || id;
function go(id) { if (location.pathname !== pathOf(id) || location.hash) history.pushState(null, '', pathOf(id)); route(); }
function idFromLoc() {
  const p = location.pathname.startsWith(BASE) ? decodeURIComponent(location.pathname.slice(BASE.length)).replace(/\/+$/, '') : '';
  const h = location.hash.slice(1), hid = unalias(h === 'new-launches' ? 'home' : h);
  if (p && !known(p) && known(unalias(p))) { history.replaceState(null, '', pathOf(unalias(p))); return unalias(p); }
  if (!p && hid && known(hid)) { history.replaceState(null, '', pathOf(hid)); route.ran = true; return hid; }
  return p && known(p) ? p : 'home';
}
function pick(id) { $('#results').hidden = true; $('#q').value = id === 'home' ? '' : CONDOS.find(c => c.id === id).name; $('#q').blur(); go(id); }
$('#q').addEventListener('input', showResults);
$('#q').addEventListener('focus', showResults);
$('#q').addEventListener('blur', () => setTimeout(() => $('#results').hidden = true, 120));
$('#q').addEventListener('keydown', e => {
  const bs = [...$('#results').querySelectorAll('button')];
  if (e.key === 'ArrowDown') { cur = Math.min(bs.length - 1, cur + 1); mark(); e.preventDefault(); }
  else if (e.key === 'ArrowUp') { cur = Math.max(0, cur - 1); mark(); e.preventDefault(); }
  else if (e.key === 'Enter') { if (!bs.length) showResults(); const b = [...$('#results').querySelectorAll('button')][Math.max(cur, 0)]; if (b) pick(b.dataset.id); e.preventDefault(); }
  else if (e.key === 'Escape') { $('#results').hidden = true; }
});
[['home', 'Browse all condos'], ['home-selling', 'Selling now'], ['home-upcoming', 'Upcoming'], ['mall-condo-study', 'Mall condo study']].forEach(([i, t]) => { const b = el('button', {type: 'button'}, t); b.onclick = () => { if (i.startsWith('home-')) { F_.status = i.slice(5); saveF(); go('home'); } else go(i); }; $('#quick').append(b); });

/* ---------- charts ---------- */
function lineChart(host, series, opt = {}) {
  host.innerHTML = '';
  const W = 760, H = opt.h || 300, P = {l: 52, r: 16, t: 14, b: 28};
  const all = series.flatMap(s => s.pts);
  if (!all.length) { host.innerHTML = '<p class="muted small">Pick at least one line.</p>'; return; }
  const xs = all.map(p => p[0]), ys = all.map(p => p[1]);
  const x0 = Math.min(...xs), x1 = Math.max(...xs);
  let y0 = Math.min(...ys), y1 = Math.max(...ys); const pad = (y1 - y0) * .08 || 1; y0 -= pad; y1 += pad;
  const step = niceStep((y1 - y0) / 5); y0 = Math.floor(y0 / step) * step; y1 = Math.ceil(y1 / step) * step;
  const X = v => P.l + (v - x0) / (x1 - x0 || 1) * (W - P.l - P.r), Yp = v => H - P.b - (v - y0) / (y1 - y0) * (H - P.t - P.b);
  let s = `<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${opt.label || 'Line chart'}">`;
  for (let v = y0; v <= y1 + 1e-9; v += step) s += `<line x1="${P.l}" x2="${W - P.r}" y1="${Yp(v)}" y2="${Yp(v)}" stroke="${css('--line')}" stroke-width="1"/><text x="${P.l - 8}" y="${Yp(v) + 4}" text-anchor="end">${opt.yfmt ? opt.yfmt(v) : comma(v)}</text>`;
  for (let v = x0; v <= x1; v++) if ((v - x0) % (opt.xEvery || 1) === 0 || v === x1) s += `<text x="${X(v)}" y="${H - 8}" text-anchor="middle">${opt.xlab ? opt.xlab(v) : (v === 2026 ? "'26*" : "'" + String(v).slice(2))}</text>`;
  if (opt.band) s += `<rect x="${X(opt.band[0])}" y="${P.t}" width="${X(opt.band[1]) - X(opt.band[0])}" height="${H - P.t - P.b}" fill="${css('--accent-soft')}" opacity=".7"/><text x="${X(opt.band[0]) + 6}" y="${P.t + 14}" style="fill:${css('--accent')}">${opt.bandLabel || ''}</text>`;
  if (opt.vline) s += `<line x1="${X(opt.vline)}" x2="${X(opt.vline)}" y1="${P.t}" y2="${H - P.b}" stroke="${css('--accent')}" stroke-dasharray="4 4"/>`;
  series.forEach(se => {
    const c = css(se.color), d = se.pts.map((p, i) => (i ? 'L' : 'M') + X(p[0]).toFixed(1) + ',' + Yp(p[1]).toFixed(1)).join('');
    s += `<path d="${d}" fill="none" stroke="${c}" stroke-width="${se.main ? 3 : 2}" stroke-linejoin="round" stroke-linecap="round" ${se.dash ? 'stroke-dasharray="7 6"' : ''} ${se.main ? '' : 'opacity=".85"'}/>`;
    const lp = se.pts[se.pts.length - 1]; s += `<circle cx="${X(lp[0])}" cy="${Yp(lp[1])}" r="${se.main ? 4.5 : 3}" fill="${c}"/>`;
  });
  s += `<line id="hl" x1="0" x2="0" y1="${P.t}" y2="${H - P.b}" stroke="${css('--muted')}" stroke-width="1" opacity="0"/><rect x="${P.l}" y="${P.t}" width="${W - P.l - P.r}" height="${H - P.t - P.b}" fill="transparent" class="hit"/></svg>`;
  host.innerHTML = s;
  const tip = el('div', {class: 'tip', hidden: ''}); host.append(tip);
  const svg = host.querySelector('svg'), hl = svg.querySelector('#hl');
  const move = e => {
    const r = svg.getBoundingClientRect(), px = (e.clientX - r.left) / r.width * W;
    const yr = Math.round(x0 + (px - P.l) / (W - P.l - P.r) * (x1 - x0)); if (yr < x0 || yr > x1) return;
    const rows = series.map(se => [se, (se.pts.find(p => p[0] === yr) || [])[1]]).filter(x => x[1] != null);
    if (!rows.length) { tip.hidden = true; return; }
    hl.setAttribute('x1', X(yr)); hl.setAttribute('x2', X(yr)); hl.setAttribute('opacity', '.5');
    tip.innerHTML = `<b>${opt.xlab ? opt.xlab(yr) : (yr === 2026 ? '2026 (Jan–Nov)' : yr)}</b><br>` + rows.map(([se, v]) => `<span style="color:${css(se.color)}">●</span> ${se.name}: ${opt.tfmt ? opt.tfmt(v) : comma(v)}`).join('<br>');
    tip.hidden = false; tip.style.left = Math.min(Math.max(X(yr) / W * r.width, 90), r.width - 90) + 'px'; tip.style.top = (Math.min(...rows.map(x => Yp(x[1]))) / H * r.height) + 'px';
  };
  svg.addEventListener('pointermove', move); svg.addEventListener('pointerleave', () => { tip.hidden = true; hl.setAttribute('opacity', '0'); });
}
function niceStep(raw) { const p = Math.pow(10, Math.floor(Math.log10(raw))), f = raw / p; return (f < 1.5 ? 1 : f < 3 ? 2 : f < 7 ? 5 : 10) * p; }
function barChart(host, rows) {
  const W = 760, H = 250, P = {l: 56, r: 10, t: 14, b: 28};
  const vals = rows.map(r => r.v), mx = Math.max(...vals, 0), mn = Math.min(...vals, 0);
  const step = niceStep((mx - mn) / 5), top = Math.ceil(mx / step) * step, bot = Math.floor(mn / step) * step;
  const Yp = v => H - P.b - (v - bot) / (top - bot) * (H - P.t - P.b), bw = (W - P.l - P.r) / rows.length;
  let s = `<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Change in value each year">`;
  for (let v = bot; v <= top + 1e-9; v += step) s += `<line x1="${P.l}" x2="${W - P.r}" y1="${Yp(v)}" y2="${Yp(v)}" stroke="${css('--line')}"/><text x="${P.l - 8}" y="${Yp(v) + 4}" text-anchor="end">${moneyK(v)}</text>`;
  rows.forEach((r, i) => { const x = P.l + i * bw + bw * .18, y = Math.min(Yp(r.v), Yp(0)), h = Math.abs(Yp(r.v) - Yp(0)); s += `<rect x="${x}" y="${y}" width="${bw * .64}" height="${Math.max(h, 1)}" rx="3" fill="${css(r.v >= 0 ? '--good' : '--bad')}" data-i="${i}"/><text x="${x + bw * .32}" y="${H - 8}" text-anchor="middle">${r.lab}</text>`; });
  s += `<line x1="${P.l}" x2="${W - P.r}" y1="${Yp(0)}" y2="${Yp(0)}" stroke="${css('--ink')}" stroke-width="1"/></svg>`;
  host.innerHTML = s; const tip = el('div', {class: 'tip', hidden: ''}); host.append(tip);
  const svg = host.querySelector('svg');
  svg.querySelectorAll('rect[data-i]').forEach(b => { b.style.cursor = 'default'; b.addEventListener('pointerenter', () => { const r = rows[+b.dataset.i], bb = svg.getBoundingClientRect(); tip.innerHTML = r.tip; tip.hidden = false; tip.style.left = Math.min(Math.max((+b.getAttribute('x') + bw * .32) / W * bb.width, 90), bb.width - 90) + 'px'; tip.style.top = (+b.getAttribute('y') / H * bb.height) + 'px'; }); b.addEventListener('pointerleave', () => tip.hidden = true); });
}

/* ---------- sections ---------- */
const SECTIONS = [['glance', 'At a glance'], ['returns', 'Price & profit'], ['mrt', 'Did the MRT help?'], ['buyers', 'Future buyers'], ['afford', 'Can upgraders afford it?'], ['plans', 'Floor plans'], ['rivals', 'Nearby competitors'], ['sources', 'Sources & word list']];
function buildMenu(list) {
  const m = $('#menu'); m.innerHTML = '';
  list.forEach(([id, t]) => { const b = el('button', {type: 'button', 'data-to': id}, t); b.onclick = () => document.getElementById(id).scrollIntoView({behavior: matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth'}); m.append(b); });
}
const obs = new IntersectionObserver(es => es.forEach(e => { if (e.isIntersecting) document.querySelectorAll('#menu button').forEach(b => b.classList.toggle('on', b.dataset.to === e.target.id)); }), {rootMargin: '-45% 0px -50% 0px'});

function srcLine(t) { return `<div class="src">Source: ${t}</div>`; }
function tile(label, value, sub, src) { return `<div class="card tile"><div class="eyebrow">${label}</div><div class="v">${value}</div>${sub ? `<div class="d">${sub}</div>` : ''}${src ? srcLine(src) : ''}</div>`; }

