  c1.innerHTML = `<div class="ctlrow"><h3>How much the example 3-bedroom gained or lost each year</h3><span class="small muted">Green = value went up that year</span></div><div class="chart" id="profitChart"></div>${srcLine('Stacked Homes yearly average psf (URA caveats) × 1,012 sq ft; 2026 is Jan–Nov')}`;
  s2.body.append(c1);
  const t = el('div', {class: 'tbl', style: 'margin-top:14px'});
  t.innerHTML = `<table><thead><tr><th>Year</th><th class="n">Avg psf</th><th class="n">Est. value</th><th class="n">Gain that year</th><th class="n">Total profit</th><th class="n">Return a year since 2014</th></tr></thead><tbody>${MODEL.rows.map(r => `<tr><td>${r.label}</td><td class="n">${money(r.psf)}</td><td class="n">${money(r.value)}</td><td class="n ${r.change > 0 ? 'up' : r.change < 0 ? 'down' : ''}">${r.change == null ? '–' : (r.change > 0 ? '+' : '') + money(r.change)}</td><td class="n">${r.profit ? money(r.profit) : '–'}</td><td class="n">${r.ann == null ? '–' : pct(r.ann, 1)}</td></tr>`).join('')}</tbody></table>`;
  s2.body.append(t);
  s2.body.append(el('p', {class: 'note', style: 'margin-top:12px'}, `Price-only profit. After paying 2014 buyer's stamp duty (about ${money(0.01 * 180000 + 0.02 * 180000 + 0.03 * 840000)}) and a 1% agent fee on sale, the real 2026 resales leave a profit of about ${moneyK(actAvg - 1200000 - (0.01 * 180000 + 0.02 * 180000 + 0.03 * 840000) - 0.01 * actAvg)}. Bank interest is not deducted.`));
  const sales = el('div', {class: 'grid g2', style: 'margin-top:14px'});
