let NRD = {}, nrLoad = {};
const loadNear = id => nrLoad[id] || (nrLoad[id] = (NEAR_V ? fetch(`/assets/near/${id}.json?v=${NEAR_V}`).then(r => r.ok ? r.json() : null) : Promise.resolve(null)).catch(() => null).then(d => { if (d) NRD[id] = d; }));
const KINDTXT = {L: 'Selling now', B: 'Launched', U: 'Upcoming', C: 'Completed'};
function nlInfo(k) {
  if (LA[k]) return {name: LA[k].name, kind: 'L', psf: LA[k].avgPsf, units: LA[k].units, when: LA[k].launch, note: 'launch average'};
  if (LBA[k]) return {name: LBA[k].name, kind: 'B', psf: LBA[k].avgPSF, units: LBA[k].units, when: LBA[k].launchShort, note: 'launch average'};
  if (UP[k]) { const e = myEst(UP[k]); return {name: UP[k].name, kind: 'U', psf: e ? Math.round((e[0] + e[1]) / 2) : null, units: UP[k].units, when: UP[k].launch, note: e ? 'our estimate' : ''}; }
  const c = COMP.find(r => r.id === k); if (c) return {name: c.name, kind: 'C', psf: c.psf, units: c.units, when: 'Completed ' + c.top, note: 'resale average'};
  return null;
}
function myPsf(id) { const i = nlInfo(id); return i && i.psf ? i : null; }
