  const withSold = rows.filter(r => r[5] != null), pctOf = r => r[5] / r[4] * 100;
  const out = withSold.filter(r => r[5] >= r[4]), fast = withSold.length ? [...withSold].sort((a, b) => pctOf(b) - pctOf(a))[0] : null, slow = withSold.length ? [...withSold].sort((a, b) => pctOf(a) - pctOf(b))[0] : null;
