  w.querySelectorAll('.chip[data-g]').forEach(c => c.onclick = () => { const g = c.dataset.g, v = c.dataset.v;
    if (g === 'beds') F_.beds = F_.beds.includes(+v) ? F_.beds.filter(b => b !== +v) : [...F_.beds, +v]; else if (['mrt', 'school', 'noEc'].includes(g)) F_[g] = !F_[g]; else F_[g] = v; sync(); });
  $('#fBudget').onchange = e => { F_.budget = +e.target.value; sync(); }; $('#fKeys').onchange = e => { F_.keys = +e.target.value; sync(); };
  $('#fScore').onchange = e => { F_.minScore = +e.target.value; sync(); }; $('#fSort').onchange = e => { F_.sort = e.target.value; sync(); };
  $('#fText').value = F_.text; $('#fText').oninput = e => { F_.text = e.target.value; sync(); };
  $('#fReset').onclick = () => { F_ = {...F0}; $('#fText').value = ''; sync(); };
  $('#trayC').onclick = () => { CMP = []; $('#cmpBox').innerHTML = ''; sync(); };
  $('#trayGo').onclick = () => { $('#cmpBox').innerHTML = `<div class="card" style="margin-bottom:14px"><div class="ctlrow"><h3>Side by side</h3><span class="small muted">Bold marks the best score in each row</span></div>${compareHTML()}</div>`; $('#cmpBox').scrollIntoView({behavior: 'smooth', block: 'start'}); };
  sync(); drawUp(w);
  w.querySelectorAll('.hstats [data-st]').forEach(b => b.onclick = () => { const v = b.dataset.st; if (v === 'mall') { go('mall-condo-study'); return; } F_.status = v; sync(); $('#find').scrollIntoView({behavior: matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth', block: 'start'}); });
  buildMenu([['find', 'Find and compare'], ['howto', 'How scores work']]);
