  <div class="keystrip">${k('Launch price', x.avgPSF ? money(x.avgPSF) + ' psf' : 'Not published', 'Average, as reported')}${x.startingPrice ? k('From', moneyK(x.startingPrice), 'At launch, as reported') : ''}${k('Homes', x.units ? comma(x.units) : 'n/a', '')}${k('Completion', String(x.top || 'TBC').replace(/\s*\(.*\)/, ''), '')}${k('Nearest MRT', x.mrt ? x.mrt.split(/[(,]/)[0].trim() : 'n/a', x.distanceMRT || '')}</div>
