function renderUpcoming(id) {
  if (UP[id].basic) return renderUpBasic(UP[id]);
  if (STD[UP[id].oldId || id]) return renderStandard(UP[id], STD[UP[id].oldId || id]);
  const x = UP[id], main = $('#main'); main.innerHTML = '';
  const e = myEst(x), g2 = gap(x, 1), g3 = gap(x, 2), w = el('div', {class: 'wrap'});
  const higher = x.nxt.filter(n => n[1] && x.land && n[1] > x.land * 1.005), lower = x.nxt.filter(n => n[1] && x.land && n[1] < x.land * 0.995);
  const read = [];
  if (x.bids === 1) read.push('Only one developer bid. Nobody else tested the price, so treat the land cost as unproven.');
  else if (g2 != null && g2 >= 10) read.push(`The winner paid ${pct(g2, 0)} more than the next bidder. That is a wide gap: the developer was far more optimistic than rivals, and has less room to price low.`);
  else if (g2 != null && g2 <= 2) read.push(`The top two bids were within ${pct(g2, 1)}. Several developers valued the land almost the same, which is a sign the land price is in line with the market.`);
  else if (g2 != null) read.push(`The winner paid ${pct(g2, 1)} more than the next bidder, a normal gap.`);
  if (x.bids >= 6) read.push(`${x.bids} bids is strong interest in the site.`); else if (x.bids && x.bids <= 3 && x.bids > 1) read.push(`Only ${x.bids} bids, which is thin interest.`);
  if (higher.length) read.push('A nearby plot has since sold at a higher land price. That later project will likely be dearer, which supports the price here.');
  if (lower.length && !higher.length) read.push('The nearby plot compared here cost less. A neighbour with cheaper land can sell for less, so do not assume this one sets the floor.');
  w.innerHTML = `<p class="small" style="margin-top:16px"><a href="#home">← All condos</a></p><div class="hero" style="padding-top:8px"><div><div class="eyebrow">Upcoming project file · not launched, not scored</div><h1>${x.name}</h1><p class="sub">${x.where} · ${x.dev}${x.slug ? ` · <a href="/project/${x.slug}/">Project page</a>` : ''}</p>
    <div class="pillrow">${x.ec ? '<span class="pill brown">Executive condo</span>' : ''}<span class="pill">${x.units} homes (estimate)</span><span class="pill">${x.tenure}</span><span class="pill">${x.mrt}</span></div>
    <p class="small muted" style="margin-top:14px">${x.launch}. Checked 10 Nov 2026.</p></div>
    <div class="verdict"><div class="eyebrow">Expected launch price</div><div style="display:flex;gap:12px;align-items:baseline;flex-wrap:wrap"><span class="big">${e ? money(e[0]) + '–' + comma(e[1]) : x.site}</span><span class="muted">psf${e ? ', my estimate' : ', listing site estimate'}</span></div>
      <ul style="margin:0;padding-left:1.1em;display:grid;gap:6px">${read.map(r => `<li>${r}</li>`).join('') || '<li>No land tender, so there is no bid to read.</li>'}</ul></div></div>
  ${mallNote(x.oldId || id)}
  <section class="part" id="bids"><div class="parthead"><h2>Land bid</h2><p>What the developer paid, and how it compared with rival bids.</p></div>
    <div class="grid g4">${tile('Land cost', x.land ? money(x.land) + ' psf' : 'No tender', x.total)}${tile('Number of bids', x.bids || '–', 'Tender closed: ' + x.close)}${tile('Winner above 2nd', g2 == null ? (x.bids === 1 ? 'Sole bid' : '–') : pct(g2, 1), x.bidders[1] ? x.bidders[1][0] : '')}${tile('Winner above 3rd', g3 == null ? '–' : pct(g3, 1), x.bidders[2] ? x.bidders[2][0] : 'Not reported')}</div>
    ${x.bidders.length ? `<div class="card" style="margin-top:14px"><h3>Bidders reported</h3><div class="bars" style="margin-top:10px">${x.bidders.map((b, i) => `<div class="row ${i ? '' : 'me'}"><span class="lab">${i + 1}. ${b[0]}</span><div class="track"><div class="fill" style="width:${b[1] / x.bidders[0][1] * 100}%"></div></div><span class="val">${money(b[1])}${i ? '<br>' + pct((b[1] / x.bidders[0][1] - 1) * 100, 1) : ''}</span></div>`).join('')}</div><p class="small muted" style="margin-top:8px">Land cost per sq ft of buildable floor area. The percentage is how far each bid was below the winner.${x.bids > x.bidders.length ? ` ${x.bids - x.bidders.length} lower bid(s) were not named in the reports.` : ''}</p></div>` : ''}</section>
  <section class="part" id="next"><div class="parthead"><h2>Next plot nearby</h2><p>From government land sale lists and tender reports. A higher land price nearby supports this project's price; a lower one lets a neighbour undercut it. Distance is a straight line between map points.${x.nxt.some(n => n[3]) ? ' Most of these plots have no street address yet, so we place them on their road or at the nearest MRT station: treat distances marked “about” as rough.' : ''}</p></div>
    <div class="tbl"><table><thead><tr><th>Site</th><th class="n">Land cost psf</th><th>Against this project</th><th>Distance</th></tr></thead><tbody>${x.nxt.map((n, i) => `<tr><td>${n[0]}</td><td class="n">${n[1] ? money(n[1]) : 'Not yet tendered'}</td><td>${n[1] && x.land ? `<span class="badge ${n[1] > x.land * 1.005 ? 'b-good' : n[1] < x.land * 0.995 ? 'b-bad' : 'b-warn'}">${nextLine(x, n).split(', ')[1]}</span>` : '–'}</td>${nxtDistCell(x, i)}</tr>`).join('')}</tbody></table></div></section>
  ${upcomingPlots(x)}
  <section class="part" id="price"><div class="parthead"><h2>Expected launch price</h2><p>Three separate views. None is the developer's price.</p></div>
    <div class="grid g3">${tile('My estimate', e ? money(e[0]) + '–' + comma(e[1]) + ' psf' : 'Not possible', e ? 'Land cost × 2.1 to 2.4' + (x.land >= 1500 ? '. For land this expensive, analysts expect a lower multiple, so treat this as the upper end.' : '') : 'No land price to work from')}${tile('Analysts at the tender', x.analyst, 'Quoted in tender reports')}${tile('Listing site cost model', x.site + ' psf', 'Estimated cost to build plus 15-30% margin')}</div>
    <details class="more"><summary>Where the 2.1 to 2.4 comes from</summary><div class="tbl"><table><thead><tr><th>Recent launch</th><th class="n">Land cost psf</th><th class="n">Launch price psf</th><th class="n">Launch ÷ land</th></tr></thead><tbody>${CAL.map(c => `<tr><td>${c[0]}</td><td class="n">${money(c[1])}</td><td class="n">${money(c[2])}</td><td class="n">${(c[2] / c[1]).toFixed(2)}</td></tr>`).join('')}</tbody></table></div><p class="small muted" style="margin-top:8px">The 11 launches range from 2.03 to 2.55, with the middle at 2.19. Prime-city projects and projects next to an MRT tend to sit higher; building costs and the market at launch can move any project outside the range.</p></details></section>
  ${upcomingFair(x)}
  <section class="part" id="quality"><div class="parthead"><h2>Developer build quality (CONQUAS band)</h2><p>BCA rates developers from Band 1 (very few major defects) to Band 6, based on their condos completed in the last 6 years.</p></div><div class="card"><p><b>${x.cq}</b></p><p class="small muted" style="margin-top:8px">BCA's list can only be searched by name on its Quality Housing Portal, and I could not pull the full list. Check the developer there before committing: <a href="https://www.bca.gov.sg/quality-housing-portal/ConquasScore.aspx" target="_blank" rel="noopener">BCA Quality Housing Portal</a>.</p></div></section>
  <section class="part" id="unsure"><div class="parthead"><h2>Points to note and not confirmed</h2></div><div class="card"><ul style="margin:0;padding-left:1.1em;display:grid;gap:6px">${[...x.notes, 'Home count, launch date and all price estimates are not from the developer', 'I did not open URA\'s Master Plan map for this site; nearby plots come from land sale lists and tender reports only'].map(u => `<li>${u}</li>`).join('')}</ul></div>
    <p class="small muted" style="margin-top:12px">Sources: ${x.src.map(a => `<a href="${a[1]}" target="_blank" rel="noopener">${a[0]}</a>`).join(' · ')}</p></section>`;
  main.append(w);
  const upMenu = [['bids', 'Land bid'], ['next', 'Next plot nearby']];
  if (x.uraPlots || x.uraNote) upMenu.push(['ura', 'Nearby URA plots']);
  upMenu.push(['price', 'Expected price']);
  if (x.fair) upMenu.push(['fair', 'Fair entry']);
  upMenu.push(['quality', 'Build quality'], ['unsure', 'Not confirmed']);
  buildMenu(upMenu);
  main.querySelectorAll('section.part').forEach(s => obs.observe(s));
}
